import { lazy, Suspense } from 'react';
import { Viewport } from '../viewport/Viewport';
import { TopBar } from '../panels/TopBar';
import { Inspector } from '../panels/Inspector';
import { StatusBar } from '../panels/StatusBar';
import { HintBar } from '../panels/HintBar';
import { useLivePreview } from '../state/useLivePreview';
import '../panels/panels.css';

const Gallery = lazy(() => import('../dev/Gallery').then((m) => ({ default: m.Gallery })));

/**
 * App shell. Owned by the integrator; feature agents do not edit this file.
 * The viewport owns the canvas; chrome floats above it and reads the store.
 */
export function App() {
  useLivePreview();

  const dev = new URLSearchParams(location.search).has('gallery');

  if (dev) {
    return (
      <Suspense fallback={null}>
        <Gallery />
      </Suspense>
    );
  }

  return (
    <div className="app-shell">
      <Viewport />
      <div className="chrome">
        <TopBar />
        <Inspector />
        <StatusBar />
        <HintBar />
      </div>
    </div>
  );
}
